insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('passport', 'Valid Passport', 'Valid for at least three (3) months after the intended return; photocopy of passport data page and all previous Schengen visa; passport must be in good condition and have a minimum of 2 pages left.', 'identity', true, 1, 'https://visa.vfsglobal.com/one-pager/austria/nigeria/english/pdf/tourist-checklist.pdf'),
  ('other_passports', 'all other valid or expired passports (ordinary – service – diplomatic)', 'If applicable: must be presented with a copy of the data page and Schengen visa in order to check whether there is a valid visa or not.', 'identity', false, 2, 'https://visa.vfsglobal.com/one-pager/austria/nigeria/english/pdf/tourist-checklist.pdf'),
  ('application_form', 'Application Form', 'Legibly and fully completed with date and signature by applicant. In case of minors -> 18 years or less: signature of parent or legal guardian.', 'application', true, 3, 'https://visa.vfsglobal.com/one-pager/austria/nigeria/english/pdf/tourist-checklist.pdf'),
  ('photos', 'Two (2) recent color passport photos', 'According to ICAO-Standard (white background).', 'photo', true, 4, 'https://visa.vfsglobal.com/one-pager/austria/nigeria/english/pdf/tourist-checklist.pdf'),
  ('flight_reservation', 'Flight reservation', 'No paid booking required; printed out including return flight (with PNR airline code).', 'travel', true, 5, 'https://visa.vfsglobal.com/one-pager/austria/nigeria/english/pdf/tourist-checklist.pdf'),
  ('introductory_letter', 'Introductory letter', 'Explaining the purpose of the travel and the travel details in original. The itinerary must be clearly described. The letter should be legibly hand-written or typed and signed by the applicant.', 'travel', true, 6, 'https://visa.vfsglobal.com/one-pager/austria/nigeria/english/pdf/tourist-checklist.pdf'),
  ('residence_permit', 'residence permit', 'Foreign nationals living in Nigeria: color copy of the residence permit.', 'residency', false, 7, 'https://visa.vfsglobal.com/one-pager/austria/nigeria/english/pdf/tourist-checklist.pdf'),
  ('medical_travel_insurance', 'Medical Travel Insurance', 'From accredited companies according to list, covering the entire period of the first intended travel, valid for all Schengen member-states and covering any expenses which might arise in connection with repatriation for medical reasons, urgency medical attention, emergency hospital treatment or death during the stay. The minimum coverage must be 30.000 EUR. Holders of diplomatic passports are generally exempted from this requirement.', 'insurance', true, 8, 'https://visa.vfsglobal.com/one-pager/austria/nigeria/english/pdf/tourist-checklist.pdf'),
  ('accommodation_proof', 'Proof of accommodation', 'For the whole duration of the intended stay, for example: hotel reservations, rental of holiday home, campus residence reservation. Proof of payment may be demanded by the Embassy in the process.', 'accommodation', true, 9, 'https://visa.vfsglobal.com/one-pager/austria/nigeria/english/pdf/tourist-checklist.pdf'),
  ('proof_of_status_employment_income', 'Proof of status/employment/income', 'Company owners: proof of company registration (original + copy), proof of tax clearance for the last years, bank statements of company minimum last 3 months, proof of sound business relations with other companies, for example references. Employees: original letter from employer with confirmation for paid leave for the travelling period, proof of employment (contract: original and copy), original pay slips on company paper covering the last three (03) months, original and copy of personal tax clearance, personal bank statements (including salary account) covering the past three (3) months. Self-employed: personal bank statements in all currencies covering the past three (3) months, proof of company registration, tax clearance minimum last 3 years, proof of sound business relations with other companies, for example references (with clear contact details). Student or school child: school attestation of actual status (grade) in original and copy signed by the head of school or responsible registrar with all contact details (phone, email, website etc.), confirming allowed absence for travel period. Family members without occupation (spouses, children etc.): proof of relationship such as marriage certificate, birth certificate etc. in original and color copy has to be provided.', 'financial', true, 10, 'https://visa.vfsglobal.com/one-pager/austria/nigeria/english/pdf/tourist-checklist.pdf'),
  ('minor_travel_consent', 'Affidavit from the other parent or legal guardian', 'If you are a minor till 18 years and travel with just one parent or someone else, in addition: affidavit from the other parent or legal guardian, allowing you to travel to Austria, sworn before the Magistrate Court plus original and photocopy of your birth certificate and that of other parent (legal guardian).', 'minor', false, 11, 'https://visa.vfsglobal.com/one-pager/austria/nigeria/english/pdf/tourist-checklist.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

