  values ('ng', 'au', 'study', 'Student visa', 1, date '2026-09-04', 'Australian Department of Home Affairs', 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500', null, null, 250000, 'AUD', true, timestamptz '2026-09-04T11:11:00.350Z', 'approved', (select id from profiles where id = 'user_3IpITvZEowYajAzuRbROwk5BWk6'), timestamptz '2026-09-04T11:11:00.350Z', null, '41f6dd91e6e79afe8a53ef43cb8b9b3dde887417c924194c7dc149b3243e7e04')
