insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('passport', 'valid passport', 'You and your family members must hold a valid passport in order to lodge a Student visa application. Provide the pages of your current passport showing your photo, personal details, and passport issue and expiry dates.', 'identity', true, 1, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('national_identity_card', 'national identity card', 'Provide a national identity card, if you have one.', 'identity', false, 2, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('name_change_proof', 'proof of change of name', 'Provide proof of change of name, if applicable. Documents can include a marriage or divorce certificate, change of name documents from an Australian Registry of Births, Deaths and Marriages or the relevant overseas authority, or documents that show other names you have been known by.', 'identity', false, 3, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('confirmation_of_enrolment', 'Confirmation of Enrolment (CoE)', 'Provide a Confirmation of Enrolment in a full time course registered on the Commonwealth Register of Institutions and courses for Overseas Students (CRICOS) for all intended courses. Your CoE must be valid at time of lodgement and when the visa application is decided.', 'study', true, 4, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('letter_of_support_dfat_scholarship', 'letter of support', 'You do not need to provide a CoE if you are enrolled in a full-time course of study or training under a scholarship scheme approved by the Australian Minister for Foreign Affairs and Trade; provide a letter of support.', 'study', false, 5, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('letter_of_support_defence', 'letter of support', 'You do not need to provide a CoE if you are sponsored by the Australian Department of Defence; provide a letter of support.', 'study', false, 6, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('aases', 'Acceptance Advice of Secondary Exchange Student (AASES) form', 'You do not need to provide a CoE if you are a secondary exchange student; provide an Acceptance Advice of Secondary Exchange Student form.', 'study', false, 7, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('education_provider_letter_thesis_marking', 'letter from your education provider', 'You do not need to provide a CoE if you are a postgraduate research student who needs to stay in Australia while your thesis is marked; provide a letter from your education provider.', 'study', false, 8, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('genuine_student_response', 'response, in English, to a set of questions', 'The online application asks you to provide a response, in English, to a set of questions. Each question has a 150 word limit addressing the genuine student criteria.', 'eligibility', true, 9, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('genuine_student_supporting_documents', 'supporting documents', 'You will also need to attach supporting documents to your application in ImmiAccount to address the Genuine Student criteria.', 'eligibility', true, 10, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('english_language_evidence', 'evidence of your English language skills', 'If required, provide evidence that you have either obtained a minimum test score in an English language test approved by the department, or met the requirements of an exemption category.', 'language', false, 11, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('financial_capacity_evidence', 'evidence of your financial capacity', 'If the document checklist requires you to give evidence of your financial capacity, you must attach evidence with your visa application. Evidence can include deposits of money from a financial institution, a government loan or loans from a financial institution, or scholarships or similar financial support.', 'financial', false, 12, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('annual_income_evidence', 'official government documents such as tax assessments', 'Alternatively, you can give evidence that your parents or your partner had a personal annual income of at least AUD87,856 in the 12 months before you apply, or at least AUD102,500 if you bring family members. Give evidence in the form of official government documents such as tax assessments less than 12 months old.', 'financial', false, 13, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('financial_supporter_relationship_evidence', 'evidence of your relationship with the person providing funds', 'If someone else is providing you funds, give evidence of your relationship with them, their identity documents, and evidence of any financial support they have given you or another Student visa holder in the past.', 'financial', false, 14, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('business_operating_proof', 'proof the business is operating', 'If you receive financial support through a business, show proof the business is operating.', 'financial', false, 15, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('deposit_source_evidence', 'evidence explaining the source of deposits of money', 'If you give evidence of deposits of money, explain their source to show how the funds were accumulated. This could include recent bank transaction statements showing the history of funds and any regular payments or growth patterns, such as from salary income.', 'financial', false, 16, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('loan_evidence', 'evidence of loan terms and disbursement', 'If you rely on an education loan and receive payments before a decision, give evidence including the terms of the loan and the full amount you will be paid. If relying on another kind of loan, provide evidence of the security used, the terms of the loan, and evidence you can cover ongoing costs.', 'financial', false, 17, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('vac_exemption_evidence', 'evidence you are exempt from paying a visa application charge (VAC)', 'Provide proof of exemption if you are a Student visa applicant not required to pay a visa application charge, as shown under Step by step, Gather your documents.', 'fee', false, 18, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('oshc_proof', 'proof of paid adequate health insurance', 'You must include proof of paid adequate health insurance for the proposed duration of your visa. Health insurance must be Overseas Student Health Cover (OSHC) covering everyone included in your application.', 'health', true, 19, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('polio_vaccination_certificate', 'polio vaccination certificate', 'If you are applying from outside Australia and you are travelling from, or spent time in, a country considered at risk of polio, you need to give a polio vaccination certificate.', 'health', false, 20, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('welfare_arrangements', 'appropriate welfare arrangements', 'If you are under 18 years old, you must have appropriate welfare arrangements in place. This must cover your period of stay or until you turn 18 years, whichever is first.', 'welfare', false, 21, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('parental_consent_under_18', 'completed and signed consent Form 1229 or a statutory declaration', 'Every applicant under the age of 18 must provide a completed and signed consent Form 1229 or a statutory declaration from each parent or legal guardian with their consent. If you cannot provide consent from both parents or guardians, provide evidence that one party has sole custody.', 'consent', false, 22, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('birth_certificate_under_18', 'birth certificate of the under 18 student', 'The birth certificate must include the names of the parents. A ceremonial or notarial certificate is not sufficient for this purpose.', 'identity', false, 23, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('parent_guardian_identity_documents', 'identity document(s) that show the signature and photo of the person(s) who completed the form or declaration', 'For an applicant under 18, provide identity document(s) that show the signature and photo of the person(s) who completed the form or declaration, such as a passport or driver''s licence.', 'identity', false, 24, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('sole_custody_evidence', 'evidence of sole custody', 'If applicable, provide evidence of sole custody such as a valid court order, death certificate or a divorce certificate/legal separation agreement.', 'custody', false, 25, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
  ('caaw', 'Confirmation of Appropriate Accommodation and Welfare (CAAW)', 'To show welfare arrangements, under 18 applicants can arrange a Confirmation of Appropriate Accommodation and Welfare (CAAW).', 'welfare', false, 26, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
