    is_live, last_verified_at, review_state, approved_by, approved_at,
    reject_reason, source_hash
  )
  values ('ng', 'cz', 'work', 'long-term visa', 1, date '2026-09-04', 'Ministry of the Interior of the Czech Republic', 'https://mv.gov.cz/mvcren/article/application-requirements-application-requirements.aspx', null, null, null, null, false, null, 'pending', null, null, null, '54fc1c8bcf53a250c61b1eff254fea3a9c288960e1dc2374a5881c9d8e48ac57')
  on conflict on constraint corridors_corridor_version_key do nothing
  returning id
)
insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('travel_document', 'Travel document', 'For the purposes of conferring a long-term visa, the travel document shall not be older than 10 years, it must contain at least 2 free pages and its validity must be at least 3 months longer than the validity of the long-term visa. For an applicant under 15 who does not have his/her own travel document, it is sufficient to submit a travel document of another foreign national (e.g. a parent) in which he/she is entered.', 'identity', true, 1, 'https://mv.gov.cz/mvcren/article/travel-document.aspx'),
  ('proof_of_funds', 'Proof of funds for the purposes of a long-term visa', 'For the purposes of a long-term visa apart from the purpose of business, a foreign national is obliged to prove the availability of funds that are 15 times the amount of the existential minimum for the first month and double the amount of existential minimum for every month afterwards. As of January 1st, 2023, the existential minimum is 3 130 CZK. A foreign national under 18 years proves the availability of half the amount. Means of demonstrating availability of funds include a bank account statement, another document on financial security, or a valid internationally recognized payment card; proof can also be substituted for by a document confirming that the costs associated with the stay in the Czech Republic have already been covered, or that services will be provided free of charge, or by a letter of invitation verified by the foreign police.', 'financial', true, 2, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('internationally_recognized_payment_card', 'A valid internationally recognized payment card', 'As long as it is not exempt from use in the Czech Republic. Upon request of an administrative body, the foreigner is obliged to simultaneously submit a statement from a bank account maintained in a bank or other financial institution, indicating that he/she is free to use the finances in the specified amount during his/her stay in the territory.', 'financial', false, 3, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('bank_account_statement', 'A bank account statement', 'For an account maintained in a bank or other financial institution in the foreign national''s name indicating that he/she is free to use the finances in the required amount during his/her stay in the territory of the Czech Republic. The submitted document must clearly indicate that the foreign national is entitled to use the requisite funds in the Czech Republic. Should this not be clear, further evidence may be required, e.g. an internationally recognised payment card issued for the bank account upon request.', 'financial', false, 4, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('other_financial_security_document', 'Another document on financial security', 'Demonstrating that the foreign national has the required amount of financial resources at his/her disposal, or that he/she has secured funds to cover the costs associated with his/her stay in the territory.', 'financial', false, 5, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('document_confirming_costs_already_covered', 'A document confirming that the costs associated with the foreign national''s stay in the Czech Republic have already been covered', 'Proof of funds in the required amount can be substituted for by this document, or by proof that services will be provided free of charge, or by a letter of invitation verified by the foreign police.', 'financial', false, 6, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('proof_services_free_of_charge', 'Proof that services will be provided free of charge', 'Proof of funds in the required amount can be substituted for by this proof, or by a document confirming that the costs associated with the foreign national''s stay in the Czech Republic have already been covered, or by a letter of invitation verified by the foreign police.', 'financial', false, 7, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('letter_of_invitation_verified_by_foreign_police', 'A letter of invitation verified by the foreign police', 'Proof of funds in the required amount can be substituted for by this letter, or by a document confirming that the costs associated with the foreign national''s stay in the Czech Republic have already been covered, or by proof that services will be provided free of charge.', 'financial', false, 8, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

