  ('proof_of_funds', 'Proof of funds', 'For the purposes of a long-term visa (apart from the purpose of business), a foreign national is obliged to prove the availability of funds that are 15 times the amount of the existential minimum for the first month and double the amount of existential minimum for every month afterwards. A foreign national under 18 years proves the availability of half the amount.', 'financial', true, 3, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('bank_account_statement', 'A bank account statement', 'A bank account statement for an account maintained in a bank or other financial institution in the foreign national’s name indicating that he/she is free to use the finances in the required amount during his/her stay in the territory of the Czech Republic. The submitted document must clearly indicate that the foreign national is entitled to use the requisite funds in the Czech Republic.', 'financial', false, 4, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('additional_evidence_of_access_to_funds', 'further evidence', 'Should it not be clear that the foreign national has the requisite financial resources at his/her disposal (e.g. in case of a foreign bank account), he/she will be required to provide further evidence, e.g. an internationally recognised payment card issued for the bank account upon request.', 'financial', false, 5, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('other_document_on_financial_security', 'Another document on financial security', 'Another document on financial security demonstrating that the foreign national has the required amount of financial resources at his/her disposal, or that he/she has secured funds to cover the costs associated with his/her stay in the territory.', 'financial', false, 6, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('internationally_recognized_payment_card', 'A valid internationally recognized payment card', 'A valid internationally recognized payment card, as long as it is not exempt from use in the Czech Republic. Upon request of an administrative body, the foreigner is obliged to simultaneously submit a statement from a bank account maintained in a bank or other financial institution, indicating that he/she is free to use the finances in the specified amount during his/her stay in the territory.', 'financial', false, 7, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('pledge_from_state_body_or_legal_entity', 'a pledge issued by a state body or legal entity', 'A foreign national who will study in the Czech Republic can submit the proof of funds in form of a pledge issued by a state body or legal entity that they will secure the foreign national’s stay in the Czech Republic by providing financial means amounting to the existential minimum for 1 month of the expected stay.', 'financial', false, 8, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('document_costs_covered_by_recipient_organisation', 'a document that all of the costs associated with his/her stay will be covered by the recipient organisation (school)', 'A foreign national who will study in the Czech Republic can submit proof of funds in the form of a document that all of the costs associated with his/her stay will be covered by the recipient organisation (school).', 'financial', false, 9, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('proof_of_difference_between_pledge_and_required_', 'a document proving he/she has the financial resources amounting to the difference', 'If the amount in the pledge does not cover the amount required by the law, the foreign national is obliged to submit a document proving he/she has the financial resources amounting to the difference between the existential minimum and the pledge for the period of the expected stay, at most, however, 6 times the amount of the existential minimum.', 'financial', false, 10, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('decision_or_contract_on_awarding_a_grant', 'a decision or contract on awarding a grant', 'The document on securing funds for the stay can be substituted for by a decision or contract on awarding a grant obtained on the basis of an international agreement by which the Czech Republic is bound.', 'financial', false, 11, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('document_confirming_costs_already_covered_or_fre', 'a document confirming that the costs associated with the foreigner national`s stay in the Czech Republic have already been covered, or that services to him will be provided free of charge', 'Proof of funds in the abovementioned amount can be substituted for by a document confirming that the costs associated with the foreigner national`s stay in the Czech Republic have already been covered, or that services to him will be provided free of charge.', 'financial', false, 12, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('verified_letter_of_invitation', 'a letter of invitation verified by the foreign police', 'Proof of funds in the abovementioned amount can be substituted for by a letter of invitation verified by the foreign police.', 'financial', false, 13, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

