insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('travel_document', 'Travel document', 'A travel document for the purposes of conferring a long-term visa shall not be older than 10 years, it must contain at least 2 free pages and its validity must be at least 3 months longer than the validity of the long-term visa. For an applicant under 15 who does not have his/her own travel document, it is sufficient to submit a travel document of another foreign national (e.g. a parent) in which he/she is entered.', 'identity_travel', true, 1, 'https://mv.gov.cz/mvcren/article/travel-document.aspx'),
  ('proof_of_funds', 'Proof of funds for the purposes of a long-term visa', 'For the purposes of a long-term visa (apart from the purpose of business), a foreign national is obliged to prove the availability of funds that are 15 times the amount of the existential minimum for the first month and double the amount of existential minimum for every month afterwards. A foreign national under 18 years proves the availability of half the amount. Means of demonstrating availability of funds include: a bank account statement in the foreign national''s name; another document on financial security demonstrating the required financial resources; a valid internationally recognized payment card (upon request of an administrative body, simultaneously with a bank account statement); or a document confirming that the costs associated with the foreign national''s stay in the Czech Republic have already been covered, that services will be provided free of charge, or a letter of invitation verified by the foreign police.', 'financial_means', true, 2, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('further_evidence_of_access_to_funds', 'further evidence', 'Should it not be clear that the foreign national has the requisite financial resources at his/her disposal (e.g. in case of a foreign bank account), he/she will be required to provide further evidence, e.g. an internationally recognised payment card issued for the bank account upon request.', 'financial_means', false, 3, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx'),
  ('bank_account_statement_with_payment_card', 'statement from a bank account', 'When submitting a valid internationally recognized payment card as proof of funds, upon request of an administrative body, the foreigner is obliged to simultaneously submit a statement from a bank account maintained in a bank or other financial institution, indicating that he/she is free to use the finances in the specified amount during his/her stay in the territory.', 'financial_means', false, 4, 'https://mv.gov.cz/mvcren/article/proof-of-funds-for-the-purposes-of-a-long-term-visa.aspx')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

