insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('application_form', 'Application Form', 'completely fill out form in English or German signed by applicant (or leageal guardian) with place and date', 'application', true, 1, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('declaration_section_54_aufenthg', 'Declaration pursuant to section 54 AufenthG', 'signed declaration by applicant (or legeal guardian) with place and date', 'application', true, 2, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('gdpr_form', 'General Data Protection Regulation', 'signed Regulations by applicant (or legeal guardian) with place and date', 'application', true, 3, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('passport', 'Applicant''s Passport', 'original passport + copy of data page; issued in the last 10 years; valid for at least 6 more months; at least two free pages', 'identity', true, 4, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('nigeria_residence_permit', 'Copy of residence permit for Nigeria as proof of a legal residence status in Nigeria', 'only for applicants with a nationality other than Nigerian', 'residency', false, 5, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('birth_certificate', 'Birth certificate', 'For births before December 15, 1992: certified copy of the local birth register extract based on the first registration; affidavit (“Declaration of Age”) of one parent or the head of the family if both parents are deceased; and copy of an identity document showing the signature of the person making the affidavit. For births at or after December 15, 1992: NPC birth certificate issued from the NPC of your place of birth; if you do not have a birth certificate from the NPC: certified copy of the local birth register extract based on the first registration, affidavit (“Declaration of Age”) of one parent or the head of the family, and copy of an identity document showing the signature of the person making the affidavit. If necessary with a note of illiteracy, preferable e-Affidavit. Head of family at least 10 years older than the applicant.', 'civil_status', true, 6, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('previous_schengen_visas', 'previous Schengen Visas as proof of travel history', 'only one copy', 'travel_history', false, 7, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('travel_health_insurance', 'Travel Health Insurance', 'Minimum coverage of €30,000; valid for the entire duration of travel; valid throughout the entire Schengen Area', 'insurance', true, 8, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('flight_reservation', 'Flight reservation/booking', 'no booked ticket required', 'travel', true, 9, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('proof_of_accommodation', 'Proof of accommodation', 'e.g.: Hotel reservation; Invitation from a family member/friend', 'accommodation', true, 10, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('proof_of_sufficient_financial_resources', 'Proof of sufficient financial resources for the planned stay', 'e.g.: bank statements for the last three months; pay slips for the last three months; formal obligation (“Verpflichtungserklärung”) according to Sec. 66 to 68 of the German Residence Act covering the entire duration of stay, signed by a person living in Germany at the local competent office in Germany. Document must be presented in Original + one copy. Not older then 6 month.', 'financial', true, 11, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('proof_of_social_and_economic_ties', 'Proof of social and economic ties to country of residence', 'Marriage certificate and birth certificates of minor children (if applicable); recent personal bank statements for the last 3 months (preferably salary account) — only bank statements issued, signed, and stamped by the bank are accepted; proof of land ownership or ownership certificate (if applicable).', 'ties', true, 12, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('employment_documents', 'If employed', 'Employment contract; Introduction letter; Holiday certificate; Salary statement for the last 3 months; COI/COR/Certificate of Incorporation/Registration of the company in Nigeria + MEMO/CAMA; FIRS/Federal Inland Revenue Service Income Tax Clearance Certificate/Company Income Tax Clearance Certificate (recent years)', 'employment', false, 13, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('self_employment_documents', 'If self-employed', 'Business registration certificate; proof of active business (bills of lading, import declaration forms, invoices) + 1 copy; COI/COR/Certificate of Incorporation/Registration + MEMO/Memorandum and Articles of Association/CAMA; FIRS Income Tax Clearance Certificate/Company Income Tax Clearance Certificate (recent years); company bank statements for 3 months', 'employment', false, 14, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('student_documents', 'For children and students', 'Introduction letter from school/university', 'education', false, 15, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('informal_invitation_letter', 'Informal invitation letter from host in Germany', 'Signed by the host. Including a copy of the passport/identity card. Including recent certificate of registration (Meldebescheinigung). If applicable: valid residence permit. Note: The formal obligation (“Verpflichtungserklärung”) does not replace the mandatory invitation letter from your host.', 'invitation', true, 16, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('proof_of_family_relationship', 'Proof of the family relationship to the inviting person', 'e.g. Birth certificate; Marriage certificate', 'civil_status', false, 17, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('purpose_of_journey_documents', 'Further documents proving purpose of journey', 'reasons for your travel', 'supporting', true, 18, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('original_documents', 'Original documents', 'all originals for the copies mentioned above must be submitted in chronological order. Your original documents will be returned to you once your application has been processed.', 'supporting', true, 19, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('biometric_photographs', '2 x biometric photograph', 'not older than 6 months; uniform white background; size: 3,5x4,5 cm; not glued or stapled to the application form', 'photo', true, 20, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('prepaid_courier_envelope', 'Prepaid courier envelope', 'a self-addressed prepaid courier envelope from any major courier service, addressed to yourself (please ensure that the address is legible to facilitate delivery)', 'logistics', true, 21, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('parents_passport_copies', 'Parents’ passports copies of the data pages', 'For minors (applicants under 18 years of age)', 'identity', false, 22, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('minor_consent_form', 'A signed consent form from the parent who is not attending the visa interview', 'For minors (applicants under 18 years of age)', 'consent', false, 23, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('parents_divorce_decree', 'parents’ divorce decree', 'For minors (applicants under 18 years of age), if applicable', 'civil_status', false, 24, 'https://nigeria.diplo.de/ng-en/2753076-2753076'),
  ('parents_death_certificates', 'parents’ death certificates', 'For minors (applicants under 18 years of age), if applicable', 'civil_status', false, 25, 'https://nigeria.diplo.de/ng-en/2753076-2753076')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

