insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('passport', 'valid passport + 2 copies of its data page', 'Only E-Passports can be accepted, no observations or renewals allowed.', 'identity_travel', true, 1, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('nigerian_residence_permit', 'copy of Nigerian residence permit', 'For non-Nigerian nationals residing in Nigeria.', 'residence_status', false, 2, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('visa_application_forms', '2 fully filled out Visa Application Forms (Application for a Residence Permit)', 'No copies required.', 'application_form', true, 3, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('section_54_declarations', '2 signed declarations according to Section 54 Paragraph 2 Nr. 8 of the German Alien''s Law', null, 'declaration', true, 4, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('passport_photos', '2 passport photos according to biometric specifications', 'One attached to application form and one loose (both identical photos).', 'photo', true, 5, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('birth_certificate_or_declaration_of_age', 'NPC birth certificate or Declaration of Age deposed to by head of Family', 'An NPC birth certificate may only be accepted if the applicant is born after December 13th, 1992.', 'civil_document', true, 6, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('curriculum_vitae', 'printed (NOT handwritten) and personally signed Curriculum Vitae', 'Stating professional career, including all certificates, diplomas, etc. until the date of the visa application, max. two pages (A4).', 'employment_qualification', true, 7, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('motivation_letter', 'printed (NOT handwritten) and personally signed letter of motivation', 'Max. one page (A4).', 'supporting_letter', true, 8, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('prepaid_courier_envelope', 'an prepaid courier envelope by any major courier service', 'Due to limited capacities; to return your passport and documents.', 'logistics', true, 9, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('approval_81a', 'approval according to § 81a residence act from the responsible alien authority in Germany', 'Applies if you have an approval according to § 81a residence act from the responsible alien authority in Germany (“Vorabzustimmung”).', 'approval', false, 10, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('originals_of_documents_attached_to_81a_approval', 'originals of the copies of the documents attached to the approval according to § 81a residence act', 'Applies if you have an approval according to § 81a residence act from the responsible alien authority in Germany (“Vorabzustimmung”).', 'supporting_document', false, 11, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('employer_declaration_employment', 'signed declaration by the employer about the employment and if applicable additional form A', '“Erklärung zum Beschäftigungsverhältnis” and if applicable “Zusatzblatt A zum Formular zur Erklärung zum Beschäftigungsverhältnis”. Applies if you do not have approval according to § 81a residence act from the responsible alien authority in Germany (“Vorabzustimmung”).', 'employment_document', false, 12, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('proof_of_professional_training_or_university_deg', 'proof of professional training or university degree', 'Applies if you do not have approval according to § 81a residence act from the responsible alien authority in Germany (“Vorabzustimmung”).', 'education_qualification', false, 13, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('proof_of_recognition', 'proof of recognition of professional training or university degree', 'Unless your university is listed as “H+” and your university degree is listed in anabin (http://anabin.kmk.org/) or your desired occupation is in a non-regulated field of occupation. Applies if you do not have approval according to § 81a residence act from the responsible alien authority in Germany (“Vorabzustimmung”).', 'recognition', false, 14, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('occupation_practice_permit', 'occupation practice permit', 'If applicable.', 'permit', false, 15, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf'),
  ('proof_of_sufficient_retirement_provisions', 'proof of sufficient retirement provisions', 'If you apply for the first time for a visa according to § 18a or § 18b Paragraph 1 of the German Alien’s Law and are older than 45 years and your salary does not exceed 45.540,- Euros per year.', 'financial', false, 16, 'https://nigeria.diplo.de/resource/blob/2311392/12ce9fd6c1b7443f2fc6893c663e3a4c/checklist-feg-eng-02---2020-data.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

