  ('nigerian_residence_permit', 'copy of Nigerian residence permit', 'For non-Nigerian nationals residing in Nigeria.', 'residence', false, 2, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('visa_application_forms', '2 fully filled Visa Application Forms (Application for a Residence Permit)', 'No copies required.', 'application_form', true, 3, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('section_54_declarations', '2 signed declarations according to Section 54 Paragraph 2 Nr. 8 of the German Alien''s Law', null, 'declaration', true, 4, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('passport_photos', '2 passport photos according to biometric specifications', 'One attached to application form and one loose (both identical photos).', 'photo', true, 5, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('school_leaving_certificates', 'school Leaving Certificates of Primary and Secondary School / WAEC Certificate', null, 'education', true, 6, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('birth_certificate_or_age_declaration', 'NPC birth certificate or Declaration of Age deposed to by head of Family', 'An NPC birth certificate may only be accepted if the applicant is born after December 13th, 1992.', 'civil_status', true, 7, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('language_course_registration', 'up to date confirmation of registration for language course', null, 'study', true, 8, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('german_language_proof', 'proof of knowledge of the German language', 'If applicable.', 'language', false, 9, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('motivation_letter', 'printed (NOT handwritten) and personally signed letter of motivation', 'Max. one page (A4).', 'letter', true, 10, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('curriculum_vitae', 'printed (NOT handwritten) and personally signed Curriculum Vitae', 'Stating all visited schools, universities as well as listing all employers until date of visa application, max. two pages (A4).', 'employment_education_history', true, 11, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('prepaid_courier_envelope', 'prepaid courier envelope by any major courier service', 'Due to limited capacities, to return your passport and documents.', 'logistics', true, 12, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('blocked_account', 'fully funded blocked German bank account', 'Bearing a minimum amount of 853,- per month / 10.236,- € for one year.', 'financial_means', false, 13, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('declaration_of_sponsorship', 'original official German declaration of sponsorship (“Verpflichtungserklärung”)', 'For the purpose of studies/ language course given before the competent German authority. Please note: Financing is usually only secured if declarant resides in Germany.', 'financial_means', false, 14, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('scholarship_proof', 'proof of a scholarship financed from German public funds or European supported funds', 'Covering the arising costs.', 'financial_means', false, 15, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('parental_consent_affidavit', 'affidavit of consent of the parents for the studies of the child in Germany', 'If applicant is a minor.', 'minor_documents', false, 16, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('parents_passport_copies', 'copy of both parents passports', 'If applicant is a minor.', 'minor_documents', false, 17, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('death_certificate', 'Death Certificate', 'If one parent is deceased.', 'minor_documents', false, 18, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf'),
  ('child_custody_court_order', 'Court Order regarding child´s custody', 'If parents are divorced.', 'minor_documents', false, 19, 'https://nigeria.diplo.de/resource/blob/2191326/14172b8fd16ee9a269b2fad7994e2dd2/checklist-sprache-eng-data.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

