insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('visa_application_forms', '2 Visa Application Forms (Application for a Residence Permit)', 'No copies required.', 'application_forms', true, 1, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('section_54_declarations', '2 signed declarations according to Section 54 Paragraph 2 Nr. 8 of the German Alien''s Law', null, 'declarations', true, 2, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('passport', 'Valid passport', 'Provide 2 copies of its data page and all pages bearing entry and exit stamps.', 'passport', true, 3, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('parent_passport_germany', '2 copies of data page of the passport of the parent living in Germany', 'Plus 2 copies of Nigerian entry visa and according entry and exit stamp, if applicable.', 'family_documents', true, 4, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('parent_german_residence_permit', '2 copies of parent`s German residence permit', null, 'residence_status', false, 5, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('passport_photos', '2 identical passport pictures according to biometric specifications', 'One attached to application form and one loose.', 'photos', true, 6, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('proof_of_residence_parent_germany', 'proof of residence of the parent living in Germany', null, 'residence_proof', true, 7, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('child_birth_certificate', 'birth certificate for the child', 'Issued by the National Population Commission at the place of birth.', 'civil_documents', true, 8, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('affidavit_of_consent_parent_nigeria', 'Affidavit of Consent of the parent remaining in Nigeria for the relocation of the child to Germany', 'Required if not personally present during application interview.', 'consent_documents', false, 9, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('sole_custody_court_order', 'Court order of competent Nigerian court stating that parent in Germany is entitled to sole custody of the child', 'Required in case whereabouts of parent living in Nigeria are unknown; also indicating that child has been heard in the matter and displaying the reasons for the decision, considering the child`s well-being.', 'court_documents', false, 10, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('written_consent_parent_germany', 'written consent of parent living in Germany for the child to join him/her', null, 'consent_documents', true, 11, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('hospital_birth_registration', 'registration of birth of the hospital and name/address of the clinic', null, 'supporting_documents', true, 12, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('school_nursery_records', 'all school records, nursery records and names/addresses of schools attended', null, 'education_documents', true, 13, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('baptismal_card', 'baptismal card and name/address of the church; year of baptism', null, 'supporting_documents', true, 14, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('german_language_c1', 'proof of German knowledge on the level C1', 'Required if child is aged 16 or older; not older than one year.', 'language_proof', false, 15, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('old_family_pictures', 'old pictures of child and family', 'If available.', 'supporting_documents', false, 16, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('prepaid_courier_envelope', 'prepaid courier envelope by any major courier service', null, 'logistics', true, 17, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('parent_nigeria_id', '2 copies of data page of passport/ identification document of the parent remaining in Nigeria', 'The following documents of at least one Nigerian parent have to be submitted if the child applies alone.', 'family_documents', false, 18, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('marriage_certificate', 'original marriage certificate and 2 copies', 'The following documents of at least one Nigerian parent have to be submitted if the child applies alone.', 'civil_documents', false, 19, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('parent_birth_certificate_or_declaration_of_age', 'NPC Birth Certificate / certified true copy from the birth registry or declaration of age', 'The following documents of at least one Nigerian parent have to be submitted if the child applies alone; deposed to by one of the parents or head of the family if both parents are deceased. Please note that an NPC birth certificate may only be accepted if the applicant is born after December 13th, 1992.', 'civil_documents', false, 20, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('affidavit_marital_status', 'affidavit of marital status of the applicant', 'The following documents of at least one Nigerian parent have to be submitted if the child applies alone; deposed to by one of the parents or head of family if both parents are deceased stating that you were not married prior to your current marriage.', 'affidavits', false, 21, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('parent_biographical_old_documents', 'all school certificates, baptismal card if applicable, any other biographically old documents (vaccination card, voter`s card etc.)', 'The following documents of at least one Nigerian parent have to be submitted if the child applies alone.', 'supporting_documents', false, 22, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('document_verification_questionnaires', '2 completely filled out questionnaires concerning the document verification process', 'The following documents of at least one Nigerian parent have to be submitted if the child applies alone.', 'questionnaires', false, 23, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('power_of_attorney', 'original power of attorney', 'Required if the minor is accompanied by an authorized representative instead of a person entitled to custody; the authorized representative also has to bring along an identification card.', 'authorization_documents', false, 24, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf'),
  ('authorized_representative_id', 'identification card', 'Required if the minor is accompanied by an authorized representative instead of a person entitled to custody.', 'identity_documents', false, 25, 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

