  values ('ng', 'de', 'business', 'Visitor Visa', 1, date '2026-09-04', 'German Embassy Abuja / Consulate General Lagos', 'https://nigeria.diplo.de/ng-en/2753076-2753076', null, null, null, null, true, timestamptz '2026-09-04T11:11:00.296Z', 'approved', (select id from profiles where id = 'user_3IpITvZEowYajAzuRbROwk5BWk6'), timestamptz '2026-09-04T11:11:00.296Z', null, '561355f8abfc7fd4492cc84734e4ec9ebf6c5a50f70fa9627a0831c83850e947')
