with c as (
  insert into corridors (
    nationality_iso, destination_iso, purpose, visa_name, version, effective_from,
    source_name, source_url, processing_weeks_min, processing_weeks_max,
    government_fee_minor, government_fee_currency,
    is_live, last_verified_at, review_state, approved_by, approved_at,
    reject_reason, source_hash
  )
  values ('ng', 'ie', 'business', 'CONFERENCE VISA CHECKLIST', 1, date '2026-09-03', 'assets.ireland.ie', 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf', null, null, null, null, true, timestamptz '2026-09-04T05:28:09.797Z', 'approved', (select id from profiles where id = 'user_3IpITvZEowYajAzuRbROwk5BWk6'), timestamptz '2026-09-04T05:28:09.797Z', null, 'e7fbe579310e1a1af10986686934c60454b21a2a96695235b9831e9b69f3b49d')
  on conflict on constraint corridors_corridor_version_key do nothing
  returning id
)
insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('passport', 'Original Passport', 'Original passport valid for at least 6 months after the intended date of arrival in Ireland. Passport must have sufficient space for a visa to be inserted, at least two empty pages are required. A copy of all stamped or containing visas pages of your passport is required.', 'identity', true, 1, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('previous_passports', 'All previous passports', 'You should submit all previous passports. The first page and a copy of all stamped or containing visas pages of your old and new passports are required.', 'identity', true, 2, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('permission_to_apply_from_country', 'Evidence of your permission to be in that country e.g. a residence card', 'If you are not a national of the country from where you are applying, you must submit evidence of your permission to be in that country. You must also have at least 3 months permission to be in that country after your intended date of departure from Ireland.', 'residence_status', false, 3, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('online_application_form', 'Fully completed and signed online application form', null, 'application_form', true, 4, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('photographs', 'Two recent photographs', 'Two recent photographs (not older than 6 months) 35x45 in colour, preferably biometric type with white background. Please write your full name on the back of the photographs you submit along with your application.', 'photos', true, 5, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('application_letter', 'A signed letter of application, including your full contact details, in English', 'The letter should outline your reason for wanting to come to Ireland; give details of any other members of your family who are currently in Ireland, the UK, or any other EU Member State; state how long you plan to stay; state that the cost of trip is being borne by yourself or, where that is not the case, details of the third party funding the costs of the trip; provide the name, phone number and e-mail address of the contract organiser in Ireland; provide reasons for obligations to return to your country; and state that you will observe the conditions of your visa, that you will not become a burden on the State and that you will leave the State on the expiry of your permission to remain.', 'cover_letter', true, 6, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('employment_letter_and_payslips', 'Employment letter and payslips', 'If applicant is employed: letter from employer on official paper, bearing the seal of the workplace, with full contact details; confirmation from your employer as to whether the proposed conference is related to your employment; pay slips for the last three months; SGK (social security) registration document and SGK "hizmet dökümü" / payment of premium.', 'employment', false, 7, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('self_employment_company_documents', 'Self-employment company documents', 'If applicant is self-employed or owner of a private company: signature circular; company registration in chamber of commerce; bulletin of the trade register; tax registration certificate of the company.', 'employment', false, 8, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('farmer_certificate', 'Farmer certificate', 'If the applicant is a farmer: farmer certificate issued by the Chamber of Agriculture.', 'employment', false, 9, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('proof_of_pension', 'Proof of pension', 'If the applicant is retired: proof of pension (either bank account or pensioner booklet).', 'employment', false, 10, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('student_enrolment_and_university_letter', 'Student enrolment and university letter', 'If the Conference is in respect the Applicant’s course of studies: evidence of enrolment; a letter from the University / course provider confirming their support of your attendance at the course, and that the conference is linked to your studies.', 'study', false, 11, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('conference_host_letter', 'Conference Details', 'Letter from conference host confirming applicant will be attending conference. The letter should include details of the nature, dates, place, duration of conference and that the registration fees have been paid. This letter should be on headed paper and clearly state the phone number, business address and email address.', 'conference', true, 12, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('bank_statements', 'Bank statements', 'If applicant is responsible for costs of this trip, detailed bank statements covering a period of 6 months immediately prior to the application showing sufficient funds to pay travel costs and sustain the applicant on arrival in Ireland. This should be accompanied by the signature circular of the bank. The applicant must have immediate access to these funds, and therefore, a fixed term savings account cannot be accepted, unless a letter is included from your bank confirming that you are allowed to withdraw money during your travel period.', 'finance', false, 13, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('sponsorship_letter_and_sponsor_evidence', 'Sponsorship letter and sponsor evidence', 'For minors and persons without their own resources, a sponsorship letter shall be submitted stating that a parent/other person shall cover the expenses, with proof of the social & professional status of the person offering to cover the expenses and proof that such a person has the resources.', 'finance', false, 14, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('hotel_reservation', 'Hotel Reservation', 'Confirmed hotel reservation valid for entire stay. The dates of the hotel reservation should correspond to your flight reservation.', 'accommodation', true, 15, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('uk_trip_information', 'UK trip information', 'If you are also visiting the UK, information about entrance to UK, permission to travel to the UK and detailed information of entire trip.', 'travel_itinerary', false, 16, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('travel_health_insurance', 'Valid travel health insurance', 'Valid travel health insurance covering any costs of repatriation for medical reasons, emergency medical care and/or emergency hospital care or death during your stay in Ireland. This insurance must be valid for the whole of this territory and this insurance must be valid minimum 3 monthly.', 'insurance', true, 17, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('migration_history_statement', 'Migration history statement', 'You should provide a comprehensive statement of your migration history, including in respect of short term / touristic travel. You should include details of migration undertaken with or without the required permissions. Where you have adverse migration history (e.g. refusal of leave to land, a requirement to depart, deportation, a refusal of an immigration or residency application) you must provide details and documentation.', 'travel_history', true, 18, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('previous_visa_refusal_details', 'Previous visa refusal details', 'If you have been refused a visa for any other country, details of this, preferably the original letter issued to you by the authorities of that country, must be submitted.', 'travel_history', false, 19, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('visa_fee_and_vfs_service_fee', 'Visa fee and VFS service fee', null, 'fees', true, 20, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('original_documents', 'All documents accompanying your application must be originals', 'You should keep copies of all the documents that you provide. If there are particular documents that you wish to have returned, please provide a list of these documents with the application to the VFS agent, and ensure they are placed in a separate folder. Please submit a photocopy of all the documents that you may need back at the time of collection.', 'document_format', true, 21, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('translations', 'Full translation for documents not in English', 'If you submit a document that is not in English, it must be accompanied by a full translation. Each translated document must contain confirmation from the translator that it is an accurate translation of the original document, the date of the translation, the translator’s full name and signature, and the translator’s contact details.', 'translations', false, 22, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

-- ---------- IN · tourism · v1 · live ----------
with c as (
  insert into corridors (
    nationality_iso, destination_iso, purpose, visa_name, version, effective_from,
    source_name, source_url, processing_weeks_min, processing_weeks_max,
    government_fee_minor, government_fee_currency,
    is_live, last_verified_at, review_state, approved_by, approved_at,
    reject_reason, source_hash
  )
  values ('ng', 'in', 'tourism', 'e-Tourist Visa', 1, date '2026-09-03', 'indianvisaonline.gov.in', 'https://indianvisaonline.gov.in/evisa/tvoa.html', null, null, null, null, true, timestamptz '2026-09-04T05:28:09.799Z', 'approved', (select id from profiles where id = 'user_3IpITvZEowYajAzuRbROwk5BWk6'), timestamptz '2026-09-04T05:28:09.799Z', null, '6eb681152ecc917615d21d4cd1dd7532d911ac0f0161ea3130d2c483ef310891')
  on conflict on constraint corridors_corridor_version_key do nothing
  returning id
)
insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('passport_bio_page', 'Scanned Bio Page of the passport showing the Photograph and Details', 'To be uploaded for e-Tourist Visa.', 'document', true, 1, 'https://indianvisaonline.gov.in/evisa/tvoa.html'),
  ('photograph', 'Recent front facing photograph with white background', 'To be uploaded mandatorily by the applicant. Digital photo requirements stated: JPEG, 10 KB to 1 MB, equal height and width, full face front view, eyes open and without spectacles, centered head, plain light colored or white background, no shadows, without borders.', 'photo', true, 2, 'https://indianvisaonline.gov.in/evisa/tvoa.html'),
  ('passport_validity', 'Passport validity', 'Applicant''s passport should have at least six months validity at the time of making application for grant of e-Visa.', 'eligibility', true, 3, 'https://indianvisaonline.gov.in/evisa/tvoa.html'),
  ('return_or_onward_ticket', 'Return ticket or onward journey ticket', 'International travellers should have return ticket or onward journey ticket.', 'travel', true, 4, 'https://indianvisaonline.gov.in/evisa/tvoa.html'),
  ('sufficient_funds', 'Sufficient money to spend during stay in India', 'International travellers should have sufficient money to spend during his/her stay in India.', 'financial', true, 5, 'https://indianvisaonline.gov.in/evisa/tvoa.html'),
