insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('application_form', 'Application form', 'Duly filled in block capitals, signed and dated by the applicant on submitting the application.', 'application', true, 1, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('photographs', 'Two recent colour passport-size photographs', 'White background, size 35 x 45 mm. 1 photograph should be glued to the visa application and the second, bearing on the reverse side the applicant’s full name, should be attached to the application with a paper clip.', 'photo', true, 2, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('passport', 'Passport', 'Valid for 6 months from the date of visa application containing at least 3 consecutive pages. Only biometric passports are accepted.', 'identity', true, 3, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('passport_biodata_copy', 'Colour photocopy of the passport page containing holder’s bio-data', null, 'identity', true, 4, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('biodata_contact_sheet', 'A sheet containing the applicant’s bio-data, phone number and active e-mail address', 'This information must be typed and signed by the applicant.', 'identity', true, 5, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('nigerian_residence_permit', 'Copy of the Nigerian Residence Permit', 'For non-Nigerian nationals living in Nigeria.', 'residence', false, 6, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('previous_current_visas', 'Colour copy of any previous and current visa including the landing stamps', 'If applicable.', 'travel_history', false, 7, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('travel_medical_insurance', 'Travel medical insurance', 'Covering the entire period of intended stay, valid for all Schengen States and covering expenses which might arise in connection with repatriation for medical reasons, urgent medical attention, emergency hospital treatment or death during the stay. The minimum coverage must be 30.000 EUR.', 'insurance', true, 8, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('itinerary_documents', 'Documents relating to the itinerary', 'Confirmation of the booking of an organised trip or any other appropriate document indicating the envisaged travel plans: flight booking. Please note that no ticket should be purchased.', 'travel', true, 9, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('transit_visa_or_entry_permit', 'Visa or other entry permit for the third country of destination; tickets for onward journey', 'In the case of transit.', 'travel', false, 10, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('proof_of_accommodation', 'Proof of accommodation for the whole duration of the intended stay', 'Hotel reservations, rental of holiday home, campus residence reservation; or proof of private accommodation (invitation) from the host.', 'accommodation', true, 11, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('host_invitation_letter', 'Letter of hospitality/guarantee', 'If using proof of private accommodation, the host/sponsor has to fill in and sign a specific letter of invitation and provide photocopy of his/her identity card or passport plus photocopy of Residence Permit if the host is a foreigner. The original letter of invitation must be forwarded by the host to the applicant and not to the Consulate General of Italy.', 'accommodation', false, 12, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('proof_of_family_ties_to_host', 'Proof of family ties/relationship with the host', 'In case of family visit: Birth certificate, marriage certificate, correspondence, etc., in addition to the letter of invitation.', 'family', false, 13, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('proof_of_kinship_eu_citizen', 'Proof of kinship', 'Applicants claiming to be family members of an Italian / E.U. citizen should provide proof of kinship by submitting a specific document duly legalized by the Italian Consulate in Lagos.', 'family', false, 14, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('employer_letter', 'Letter from the applicant''s employer', 'Stating professional status of applicant and period of leave.', 'employment', true, 15, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('school_university_letter', 'Letter from school or university', 'For scholars (professors, scholarship-holders, lecturers, instructors, etc.) and students.', 'education', false, 16, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('bank_statement', 'Personal bank statement covering the last six months', 'Compulsory.', 'finance', true, 17, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('financial_investments', 'Documentation pertaining to financial investments', 'If applicable.', 'finance', false, 18, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('pit_certificate', 'Certificate of payment of tax on personal income (PIT)', null, 'finance', true, 19, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('employment_letter', 'Letter of employment', 'Stating duration of employment and financial terms.', 'employment', true, 20, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('pay_slips', 'Pay-slips covering the last six months', 'If applicable.', 'employment', false, 21, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('tcc_and_business_incorporation', 'Tax Clearance Certificate (TCC) and Certificate of Business Incorporation', 'In case the applicant is the owner of a company or an individual trader; certificate of registration of a company or business.', 'business', false, 22, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('proof_of_commercial_activities', 'Proof of commercial activities in Nigeria and overseas', 'For businesspersons, e.g. bills of lading, receipt book, Form C.O. 7 or equivalent (listings of the Company’s Directors), etc.', 'business', false, 23, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('bank_guarantee', 'Bank guarantee (fidejussione bancaria) established by the host person in Italy', 'Should be submitted in case the applicant cannot provide evidence of personal income. The amount has to be established in accordance with the relevant decree of the Italian Ministry of Interior.', 'finance', false, 24, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('proof_of_integration', 'Proof of integration into the country', 'Documents attesting the applicant’s professional status.', 'supporting', true, 25, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('marriage_certificate', 'Marriage certificate', 'If applicable.', 'family', false, 26, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('child_application_signed_by_both_parents', 'Visa application form signed by both parents', 'In case of a child applying for a tourist visa.', 'minor', false, 27, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('parents_marriage_certificate', 'Marriage certificate of the parents', 'If applicable, for a child applying for a tourist visa.', 'minor', false, 28, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('child_birth_certificate', 'Birth certificate of the child issued by the National Population Commission', 'Compulsory for a child applying for a tourist visa. Birth certificates issued by hospitals are not accepted.', 'minor', false, 29, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('school_letter_for_child', 'Letter from the school', 'Stating the class attended and giving permission of absence, for a child applying for a tourist visa.', 'minor', false, 30, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('non_travelling_parent_consent', 'Written consent in the form of a Sworn Affidavit issued by a High Court', 'If the child is travelling with one of the two parents, the parent who is not travelling with the child should give this consent, including the parent’s identity photograph and copy of his/her passport.', 'minor', false, 31, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('custody_court_order', 'Court order declaring full custodianship', 'If the child is under the sole guardianship of one of the two parents.', 'minor', false, 32, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf'),
  ('original_and_copy_of_documents', 'All documents in original and copy', 'All the documents should be provided in original and copy. Original documents will be returned to applicants while copies will be kept with the visa application. No photocopy will be accepted, except the photocopy of the identity card or passport of the inviting party residing in Italy.', 'submission', true, 33, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/Tourist_150116.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

