  ('passport_biodata_photocopies', 'Colour photocopy(2copies) of the passport page containing holder’s bio-data', null, 'identity', true, 4, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('biodata_contact_sheet', 'A sheet containing the applicant’s bio-data, phone number and active e-mail address', 'This information must be typed and signed by the applicant.', 'identity', true, 5, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('nigerian_residence_permit', 'Copy of the Nigerian Residence Permit', 'Required for non-Nigerian nationals living in Nigeria.', 'residency', false, 6, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('previous_current_visas', 'Colour copy of any previous and current visa including the landing stamps', 'If applicable.', 'travel_history', false, 7, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('travel_medical_insurance', 'Travel medical insurance', 'Covering the entire period of intended stay, valid for all Schengen States and covering any expenses which might arise in connection with repatriation for medical reasons, urgent medical attention, emergency hospital treatment or death during the stay. The minimum coverage must be 30.000 EUR.', 'insurance', true, 8, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('invitation_letter_italian_company', 'Original letter of invitation from an Italian company', 'Must be written on the Italian company’s letterhead as per the specific model (“Lettera d’invito aziendale”) and contain relevant personal data of the invited, purpose of the visit and duration of stay. It must be accompanied by the photocopy of the signatory’s Identity Card (or passport) and copy of the Italian company’s registration with the Italian Chamber of Commerce ("Visura Camerale"). These documents have to be submitted by applicants and not transmitted by the Italian companies to the Consulate General of Italy.', 'business', true, 9, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('proof_previous_business', 'Proof of previous business conducted with Italian Companies', 'Invoices, Bills of Lading, sales/distribution agreements, etc.; if applicable, or with companies from other Countries.', 'business', false, 10, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('company_incorporation_documents', 'Certificate of Incorporation + Memorandum and Articles of Association or Certificate of Business Name Registration', 'Proof of business activities carried on by the Nigerian company.', 'business', true, 11, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('company_directors_list', 'Form C.O. 7 or equivalent (listings of the Company’s Directors)', 'Proof of business activities carried on by the Nigerian company.', 'business', true, 12, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('company_tax_clearance', 'Income Tax Clearance Certificate', 'Proof of business activities carried on by the Nigerian company.', 'financial', true, 13, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('company_bank_statement', 'Company’s bank statement covering the last six months', 'Proof of business activities carried on by the Nigerian company.', 'financial', true, 14, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('nigerian_company_letter', 'Letter of the Nigerian company', 'Stating: purpose of the visit; applicant’s employment status in the company; details regarding activities and business relations with the Italian company.', 'employment', true, 15, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('fair_entry_tickets', 'Entry tickets for fairs', 'If appropriate.', 'travel', false, 16, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('hotel_reservation', 'Hotel reservation', null, 'accommodation', true, 17, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('flight_booking', 'Flight booking', 'Please note that no ticket should be purchased.', 'travel', true, 18, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('personal_bank_statement', 'Personal bank statement covering the last six months', 'Proof of financial means in the country of residence; compulsory.', 'financial', true, 19, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('financial_investment_documents', 'Documentation pertaining to financial investments', 'If applicable.', 'financial', false, 20, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('personal_income_tax_certificate', 'Certificate of payment of tax on personal income (PIT)', null, 'financial', true, 21, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('employment_letter', 'Letter of employment', 'Stating duration of employment and financial terms.', 'employment', true, 22, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('pay_slips', 'Pay-slips covering the last six months', 'If applicable.', 'employment', false, 23, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('owner_company_incorporation_documents', 'Certificate of Incorporation + Memorandum and Articles of Association or Certificate of Business Name Registration', 'Required in case the applicant is the owner of a company or an individual trader.', 'business', false, 24, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
  ('owner_company_directors_list', 'Form C.O. 7 or equivalent (listings of the Company’s Directors)', 'Required in case the applicant is the owner of a company or an individual trader.', 'business', false, 25, 'https://visa.vfsglobal.com/one-pager/italy/nigeria/english/pdf/BisinessVisa_150116.pdf'),
