  ('health_declaration_form', 'Health Declaration Form', 'You will be required to fill up and submit a copy of the health declaration form. If making an online application, upload the scanned copy of the form.', 'medical', true, 5, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
  ('academic_certificates_and_transcripts', 'Your academic certificates and transcripts', 'Provide copies of all academic records, certificates or transcripts of studies previously undertaken. Some courses have additional entry requirements; check the entry requirements provided by your educational institution.', 'education', true, 6, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
  ('yellow_fever_vaccination_booklet_card', 'yellow fever vaccination booklet/card', 'Required only if you are coming from a country considered to be at a high risk of yellow fever. You will be asked to provide it before you can clear Immigration at the point of entry.', 'medical', false, 7, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
  ('personal_bond', 'Personal Bond', 'The Immigration Department requires all education institutions in Malaysia to sign a personal bond on behalf of the candidate, binding the University for a specified sum. The institution will require you to lodge the specified amount for this purpose. The personal bond form can be submitted after you have arrived in Malaysia for the student pass endorsement.', 'financial_guarantee', true, 8, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
