  ('passport', 'passport', 'Passport must be valid for at least three months after the end of your visit and must be issued within the last ten years.', 'identity', true, 2, 'https://www.udi.no/en/want-to-apply/visit-and-holiday/visitors-visa-to-norway/?c=nga'),
  ('travel_insurance', 'valid travel insurance', 'You must have valid travel insurance.', 'insurance', true, 3, 'https://www.udi.no/en/want-to-apply/visit-and-holiday/visitors-visa-to-norway/?c=nga'),
  ('proof_of_funds', 'enough money to finance your stay in Norway and your return journey', 'You must be able to document that you have sufficient means to support yourself during your stay in Norway and the Schengen area. General guidelines stated: NOK 300 per day if staying with family or friends, or in accommodation paid for in advance; NOK 1,300 per day if you have not documented pre-booked or pre-paid accommodation for the entire duration of your stay; if several people are travelling together, at least NOK 1,000 per person per day.', 'financial', true, 4, 'https://www.udi.no/en/want-to-apply/visit-and-holiday/visitors-visa-to-norway/?c=nga'),
