  ('invitation_letter', 'invitation from the person you are visiting', 'If you are visiting someone in Norway, you must have an invitation from the person you are visiting.', 'supporting_documents', false, 8, 'https://www.udi.no/en/want-to-apply/visit-and-holiday/visitors-visa-to-norway/?c=nga'),
  ('accommodation_booking', 'booked accommodation', 'You must normally have booked accommodation for the whole time period of your stay in the Schengen area.', 'accommodation', true, 9, 'https://www.udi.no/en/want-to-apply/visit-and-holiday/visitors-visa-to-norway/?c=nga')
