from c, (values
  ('application_fee', 'application fee', 'You must pay an application fee.', 'fee', true, 1, 'https://www.udi.no/en/want-to-apply/work-immigration/skilled-workers/?c=nga'),
  ('education_or_qualifications', 'education/qualifications', 'You must have one of the following types of education/qualifications: a completed vocational training programme of at least three years at upper secondary school level, with a corresponding vocational training programme in Norway; completed education or degree from a university/university college; or special qualifications acquired through long professional experience, possibly in combination with courses and education.', 'eligibility', true, 2, 'https://www.udi.no/en/want-to-apply/work-immigration/skilled-workers/?c=nga'),
  ('work_experience_certificates', 'detailed work certificates from previous employers', 'If you are relying on special qualifications through long professional experience, you must present detailed work certificates from previous employers showing that you have learned and can do the same as a person with a professional education in the occupation. Generally, you must have at least six years of work experience.', 'supporting_document', false, 3, 'https://www.udi.no/en/want-to-apply/work-immigration/skilled-workers/?c=nga'),
  ('concrete_job_offer', 'concrete job offer from one specific employer in Norway', 'You must have received a concrete job offer from one specific employer in Norway.', 'employment', true, 4, 'https://www.udi.no/en/want-to-apply/work-immigration/skilled-workers/?c=nga'),
  ('job_offer_confirmation', 'confirmation of the job offer', 'If you are applying on your own from abroad, your employer must submit confirmation of the job offer before you can submit the application form. You will receive a code from your employer that you must enter in the application form. If you have more than one employer, only one of them must submit a confirmation form.', 'supporting_document', false, 5, 'https://www.udi.no/en/want-to-apply/work-immigration/skilled-workers/?c=nga'),
  ('full_time_job', 'full-time job offer', 'The job must normally be full-time. If you have been offered at least an 80% position, this will be accepted.', 'employment', true, 6, 'https://www.udi.no/en/want-to-apply/work-immigration/skilled-workers/?c=nga'),
  ('job_requires_skilled_worker_qualifications', 'job requiring qualifications as a skilled worker', 'The job you are offered must require qualifications as a skilled worker, and you must have the qualifications that the job requires.', 'employment', true, 7, 'https://www.udi.no/en/want-to-apply/work-immigration/skilled-workers/?c=nga'),
  ('pay_and_working_conditions', 'pay and working conditions', 'The pay and working conditions must not be poorer than is normal in Norway.', 'employment', true, 8, 'https://www.udi.no/en/want-to-apply/work-immigration/skilled-workers/?c=nga'),
  ('recognition_or_authorisation', 'recognition or authorisation', 'If you are going to work in an occupation for which recognition or authorisation is required, you must have such recognition or authorisation.', 'authorisation', false, 9, 'https://www.udi.no/en/want-to-apply/work-immigration/skilled-workers/?c=nga'),
  ('assignment_list', 'list of assignments', 'If you are to work through a staffing agency, you must present a list of the assignments that the employer has planned for you. The assignments must be confirmed by the business or businesses you are carrying out the assignments for.', 'supporting_document', false, 10, 'https://www.udi.no/en/want-to-apply/work-immigration/skilled-workers/?c=nga')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

