  ('embassy_checklist_documents', 'the documents on the embassy’s checklist', 'You must hand in all the documents on the embassy’s checklist. You will find the checklist by clicking on the “How to apply”-button below and choosing the country you live in.', 'supporting_documents', true, 2, 'https://www.udi.no/en/want-to-apply/visit-and-holiday/visitors-visa-to-norway/?c=nga'),
