from c, (values
  ('personalised_checklist', 'Personalised checklist', 'Once you complete the application form electronically, you will receive a personalised checklist based on your situation. If you have already applied, you can log in and find the checklist on your application.', 'checklist', true, 1, 'https://www.udi.no/en/word-definitions/checklists-which-explain-which-documents-you-must-hand-in-with-your-application/'),
  ('passport', 'A valid national identity card or passport', null, 'identity', true, 2, 'https://www.udi.no/en/word-definitions/checklists-which-explain-which-documents-you-must-hand-in-with-your-application/'),
  ('family_relationship', 'Documentation of the family relationship', 'For example marriage certificate or birth certificate.', 'relationship', true, 3, 'https://www.udi.no/en/word-definitions/checklists-which-explain-which-documents-you-must-hand-in-with-your-application/'),
  ('sponsor_basis_for_residence', 'Documentation of the basis for residence of the EU/EEA national that you came to Norway with or wish to be reunited with', 'If employee: documentation which shows that he or she is working, for example pay slips, employment contract and/or a confirmation from the employer. If self-employed: documentation which shows that he or she is self-employed, for example preliminary accounts or income statement, invoices, transcript from the Brønnøysund register centre, proof of registration in the VAT register, contracts/receipts for purchase/rental of business premises, car, equipment or similar. If student: documentation which shows that he or she is a student at an accredited educational institution or an upper secondary school, and a declaration which states that he or she has enough funds to support him/herself and the family. If person with own funds: documentation which shows that he or she has enough funds to support him/herself and the family, for example a pension or money in a bank account.', 'sponsor_status', true, 4, 'https://www.udi.no/en/word-definitions/checklists-which-explain-which-documents-you-must-hand-in-with-your-application/'),
  ('private_health_insurance', 'Documentation which shows that you have private health insurance which is valid for the coming 12 months', 'Applies if the EU/EEA national who you came to Norway with or wish to be reunited with is staying in Norway as a student or with own funds.', 'insurance', false, 5, 'https://www.udi.no/en/word-definitions/checklists-which-explain-which-documents-you-must-hand-in-with-your-application/'),
  ('other_parent_consent_or_custody_order', 'Written consent from the other parent, together with a certified copy of his or her valid photo ID, or a court order stating that the parent living in Norway has full parental responsibility', 'Applies if the family member is under the age of 18, and only one parent is going to live in Norway. The consent must be confirmed by a Notary Public.', 'parental_responsibility', false, 6, 'https://www.udi.no/en/word-definitions/checklists-which-explain-which-documents-you-must-hand-in-with-your-application/'),
  ('minor_parent_attendance', 'One of your parents must go with you when you hand in your application to the police or at a VFS Application Centre/embassy', 'Applies if you are under 18. It is sufficient that only one of your parents goes with you, as long as you include valid ID documentation for both parents.', 'application_submission', false, 7, 'https://www.udi.no/en/word-definitions/checklists-which-explain-which-documents-you-must-hand-in-with-your-application/'),
  ('both_parents_id', 'Valid ID documentation for both parents', 'Applies if you are under 18 and only one parent accompanies you when you hand in your application.', 'identity', false, 8, 'https://www.udi.no/en/word-definitions/checklists-which-explain-which-documents-you-must-hand-in-with-your-application/'),
  ('minor_registration_consent', 'Written statement, with signature, in which he or she gives consent for you to be registered in Norway, in accordance with the EEA regulations', 'Applies if you are under 18. The parent who will not be accompanying you must provide this statement.', 'parental_responsibility', false, 9, 'https://www.udi.no/en/word-definitions/checklists-which-explain-which-documents-you-must-hand-in-with-your-application/'),
  ('document_translation', 'Translation into Norwegian or English by an authorised/certified translator', 'If your documents are in a different language than Norwegian or English, they have to be translated to Norwegian or English by an authorised/certified translator. It must be stated on the translation who translated the document and when.', 'translation', false, 10, 'https://www.udi.no/en/word-definitions/checklists-which-explain-which-documents-you-must-hand-in-with-your-application/')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

