  ('passport', 'passport', 'Passport must be valid for at least three months after the end of your visit and must be issued within the last ten years.', 'identity', true, 2, 'https://www.udi.no/en/want-to-apply/visit-and-holiday/visitors-visa-to-norway/?c=nga'),
  ('travel_insurance', 'valid travel insurance', 'You must have valid travel insurance.', 'insurance', true, 3, 'https://www.udi.no/en/want-to-apply/visit-and-holiday/visitors-visa-to-norway/?c=nga'),
  ('proof_of_funds', 'documentation that you have sufficient means to support yourself during your stay in Norway and the Schengen area', 'You must have enough money to finance your stay in Norway and your return journey, and be able to document sufficient means to support yourself during your stay in Norway and the Schengen area.', 'financial', true, 4, 'https://www.udi.no/en/want-to-apply/visit-and-holiday/visitors-visa-to-norway/?c=nga'),
  ('sponsorship_form', 'sponsorship form', 'If you do not have enough money yourself, the person or company you are visiting must fill out a sponsorship form, which can be either electronic or on a paper form.', 'financial', false, 5, 'https://www.udi.no/en/want-to-apply/visit-and-holiday/visitors-visa-to-norway/?c=nga'),
  ('fingerprints', 'fingerprints', 'You must register your fingerprints.', 'biometric', true, 6, 'https://www.udi.no/en/want-to-apply/visit-and-holiday/visitors-visa-to-norway/?c=nga'),
  ('parental_signature', 'signature from both parents, or other persons responsible for you', 'If you are under the age of 18, both your parents, or other persons responsible for you, must sign your application.', 'consent', false, 7, 'https://www.udi.no/en/want-to-apply/visit-and-holiday/visitors-visa-to-norway/?c=nga'),
  ('business_invitation', 'invitation from the people you are going to have meetings with', 'You must have an invitation from the people you are going to have meetings with.', 'invitation', true, 8, 'https://www.udi.no/en/want-to-apply/visit-and-holiday/visitors-visa-to-norway/?c=nga')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

