from c, (values
  ('visa_application_form', 'A visa application form', 'Filled via the e-konsulat system, printed and signed.', 'application', true, 1, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('photo', 'A 3.5 x 4.5 cm colour photo', 'Photo must be sharp, against white background, printed on high quality paper, newer than 6 months, taken en face, clearly showing the eyes and face from both sides from the top of the head to the top of the shoulders with the face covering 70-80% of the photo, and taken without any headwear.', 'photo', true, 2, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('passport', 'Passport', 'Issued within last ten years, valid for at least three months from the expected return date, with at least two blank pages for visas.', 'passport', true, 3, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('other_valid_passport', 'Another valid passport', 'If you have another valid passport, you should attach it to the visa application form.', 'passport', false, 4, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('passport_copy', 'A copy of the passport page with personal data and a photo', null, 'passport', true, 5, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('flight_reservation', 'A copy of flight ticket or flight reservation including return flight', null, 'travel', true, 6, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('travel_medical_insurance', 'Travel medical insurance', 'Applicants for a Schengen Visa (single or double entries) should demonstrate adequate and valid travel medical insurance covering expenses that may arise during their stay relating to return for medical reasons, urgent medical care, emergency inpatient treatment or death. Insurance must be valid throughout the territory of the Member States of the European Union, cover the entire period of the planned stay, and have a minimum amount of EUR 30,000.', 'insurance', true, 7, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('insurance_first_visit_multiple_entry', 'Travel medical insurance for the period of the first intended visit', 'Multiple-entry visa applicants should demonstrate that they have adequate and valid travel medical insurance for the period of their first intended visit.', 'insurance', false, 8, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('id_residence_proof', 'Copy of an ID document to confirm residence within the consular district of your application', null, 'residence', true, 9, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('proof_of_means', 'Proof that you have enough means of subsistence', 'In the form decided by the mission, such as a valid bank account statement issued by your bank or balance over the last 3 months, a valid credit card with a certificate of means available, a valid income certificate from your employer for the last three months and salary slips, pension slips, or regular income generated by property.', 'financial', true, 10, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('accommodation_proof', 'A proof of accommodation', 'For example, an official invitation or a hotel booking or reservation.', 'accommodation', true, 11, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('purpose_of_stay_document', 'A document to confirm the purpose and the conditions of your planned stay in Poland', null, 'purpose', true, 12, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('hotel_reservation_or_other_accommodation', 'Hotel reservation or proof of other accommodation', 'Tourism – additional documents.', 'accommodation', true, 13, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('registered_invitation_if_staying_with_family_or_', 'Invitation registered with appropriate Polish authorities (Urzad Wojewodzki)', 'Required for applicants planning to stay with family or friends or being sponsored by Polish/EU citizens in any other way.', 'invitation', false, 14, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('tourism_financial_documents', 'Documents regarding applicant’s sufficient means of subsistence during intended stay', 'Such as introduction letter from employer with employer’s consent for travel; salary slips; proof of business ownership; personal/business bank account statements; proof of income generated by property; letter from sponsor and documents regarding sponsor’s financial situation.', 'financial', true, 15, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('proof_of_employment', 'Proof of employment', 'Tax Clearance Certificate (TCC) and Certificate of Business Incorporation paper for businesspersons. Employment letter stating the days of leave for employees.', 'employment', true, 16, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('school_or_university_letter', 'Letter from school or university', 'For scholars (professors, scholarship-holders, lecturers, instructors, etc.) and students.', 'education', false, 17, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('proof_of_commercial_activities', 'Proof of commercial activitied in Nigeria and overseas for businesspersons', 'For example bills of lading, receipt book etc.', 'business', false, 18, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('proof_of_ties_in_nigeria', 'Any proof of ties in Nigeria', 'For example marriage certificate, proof or real estate property.', 'residence', true, 19, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('document_sets', 'Two (2) sets of documents for a visa application', 'One original set of documents and one set of photocopies. All documents for the set of photocopies should be in A4 size paper.', 'submission', true, 20, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

