insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('visa_application_form', 'A completed visa application form filled via the e-konsulat system, printed and signed.', null, 'application_form', true, 1, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('photo', 'A 3.5 x 4.5 cm colour photo.', 'The photo must be sharp, taken against white background and printed on a quality paper, newer than 6 months, taken straight ahead, clearly showing the eyes and face on both sides from the top of the head to the top of the shoulders, with the face covering 70-80% of the photo. The photo must be taken without any headwear.', 'photo', true, 2, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('passport', 'Passport', 'Issued within the last 10 years, valid for at least three months from the expected return date, with at least two blank pages for visas. If you have a second valid passport, please attach it to your visa application.', 'passport', true, 3, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('passport_copy', 'A copy of the passport page with personal data and the photo.', null, 'passport', true, 4, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('flight_reservation', 'A copy of flight ticket or flight reservation including return flight.', null, 'travel', true, 5, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('medical_insurance', 'A document confirming the possession of travel medical insurance or a document confirming the possession of health insurance', 'Travel medical insurance with an insurance amount of no less than EUR 30,000 must be valid for the period of the intended stay of the foreigner on the territory of the Republic of Poland, cover all expenses that may arise during the stay due to the necessity of return travel for medical reasons, the need for urgent medical assistance, emergency hospital treatment or death, and the insurer undertakes to cover healthcare costs directly to the provider on the basis of a bill issued by that entity.', 'insurance', true, 6, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('legal_residence', 'A document to confirm legal residence within the consular district of your application.', null, 'residence_status', true, 7, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('financial_resources', 'Documents confirming the possession of financial resources to cover the costs of return travel and the costs of stay in Poland.', 'The minimum required amount is stated as: if applicant is alone in Poland, 2 500 PLN for a return trip, cost of accommodation on the basis of hotel booking or rental agreement, and 776 PLN for every month of stay; if applicant stays in Poland with family members, 2 500 PLN for a return trip, cost of accommodation on the basis of hotel booking or rental agreement, and 600 PLN for every month of stay for the applicant and each family member. Required documents confirming possession of financial resources are to be selected from the listed options; there is no obligation to present all of them.', 'finance', true, 8, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('bank_statement', 'Original bank statement from the last 6 months', 'Containing contact details of the bank employee responsible for confirming documents. Listed as one of the selectable documents confirming possession of financial resources.', 'finance', false, 9, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('polish_bank_certificate', 'The original certificate of the possession of funds in a bank having its registered office in the territory of the Republic of Poland.', 'Listed as one of the selectable documents confirming possession of financial resources.', 'finance', false, 10, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('sponsorship_letter', 'The original of the sponsorship letter confirmed by the consul', 'If the applicant does not cover his stay in Poland by himself. The sponsor confirms that he has funds to cover the costs of the return trip and the costs of the applicant''s stay in Poland on the basis of the listed banking documents. Only a family member may be a sponsor; when submitting the documents, the applicant should present documents confirming the relationship between the applicant and the sponsor.', 'finance', false, 11, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
