  ('fingerprints', 'Fingerprints', 'Applicant have submitted fingerprints as part of an earlier application which has been entered in the VIS within the last 59 months and is therefore exempted from providing new fingerprints.', 'biometrics', false, 5, 'https://visa.vfsglobal.com/one-pager/sweden/Nigeria/english/pdf/tourism_nigeria_checklist.pdf'),
  ('photograph', '1 color photograph not older than six months', 'This is only compulsory for children between the age of 0-12 years or if you do not appear in person at time of lodgment but have biometrical data submitted in a previous Schengen visa application within the last 59 months which can be reused.', 'photo', false, 6, 'https://visa.vfsglobal.com/one-pager/sweden/Nigeria/english/pdf/tourism_nigeria_checklist.pdf'),
