  ('flight_reservation', 'Copy of flight ticket or flight reservation including return flight', null, 'travel', true, 8, 'https://visa.vfsglobal.com/one-pager/sweden/Nigeria/english/pdf/tourism_nigeria_checklist.pdf'),
